import os, sys, json, argparse
import numpy as np
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot

r=Robot(); spec=r.spec(); cams=list(spec['cameras']); dt=spec['control_dt']

def save(res,name):
    path='/app/runs/'+name
    res.save(path)
    print(json.dumps({'name':name,'meta':{k:v for k,v in res.meta.items() if k!='cameras'},'proprio':res.meta.get('proprio',{}).get('now')},indent=2))
    return res

def motion(steps,dx=0,dy=0,dz=0,grip=-1,name='move'):
    A=np.tile([dx,dy,dz,grip],(steps,1)).astype(np.float64)
    return save(r.submit('ee_delta',A,dt=dt,cameras=cams,video='frames',include_depth=True,note=name),name)

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('cmd',choices=['observe','motion']);p.add_argument('--steps',type=int,default=1);p.add_argument('--dx',type=float,default=0);p.add_argument('--dy',type=float,default=0);p.add_argument('--dz',type=float,default=0);p.add_argument('--grip',type=float,default=-1);p.add_argument('--name',default='check');a=p.parse_args()
    if a.cmd=='observe':save(r.get_obs(cameras=cams,include_depth=True,video='frames'),a.name)
    else:motion(a.steps,a.dx,a.dy,a.dz,a.grip,a.name)
PY
